import heapq

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def astar(start, goal, reverse=False):
        visited = {}
        q = [(heuristic(start, goal), start, [start])]
        while q:
            h, pos, path = heapq.heappop(q)
            if pos == goal:
                return path
            if pos in visited:
                continue
            visited[pos] = path
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                if reverse:
                    dr, dc = -dr, -dc
                nr, nc = pos[0]+dr, pos[1]+dc
                next_pos = (nr, nc)
                if not is_wall(next_pos) and next_pos not in visited:
                    heapq.heappush(q, (heuristic(next_pos, goal) + len(path), next_pos, path + [next_pos]))
        return None

    forward_path = astar(start, goal)
    if forward_path:
        return forward_path
    return []
