from collections import deque

def solve(grid, start, goal):
    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    if start == goal:
        if is_wall(*start):
            return []
        return [start]

    if is_wall(*start) or is_wall(*goal):
        return []

    def a_star(source, target, reverse=False):
        visited = {}
        queue = deque()
        queue.append((source, [source]))
        visited[source] = True

        while queue:
            pos, path = queue.popleft()
            r, c = pos

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if not is_wall(nr, nc) and (reverse and (nr, nc) == target or (nr, nc) == source):
                    if reverse:
                        return path[:-1] + [(nr, nc)] + list(reversed(path))
                    else:
                        return path + [(nr, nc)]
                if not is_wall(nr, nc) and ((nr, nc) not in visited):
                    visited[(nr, nc)] = True
                    queue.append(( (nr, nc), path + [(nr, nc)] ))
        return None

    result = a_star(start, goal, False)
    if result:
        return result
    result = a_star(goal, start, True)
    return result if result else []
