    rows, cols = len(grid), len(grid[0])

    def is_wall(pos):
        r, c = pos
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    if is_wall(start) or is_wall(goal):
        return []

    if start == goal:
        return [start]

