            return None
        if current == goal:
            return [current]
        visited.add(current)
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            next_pos = (nr, nc)
            if not is_wall(next_pos) and next_pos not in visited:
                result = dls(next_pos, depth - 1, visited)
                if result is not None:
                    return [current] + result
        return None

    def iddfs():
        max_depth = 0
        while True:
            max_depth += 1
            visited = set()
            path = dls(start, max_depth, visited)
            if path:
                path.reverse()
                path = path[::-1][1:] if path[0] != start else path
                if path and path[0] == start:
                    return path
                else:
                    return [start] + path
            if max_depth > rows + cols:
                return []

    path = iddfs()
    if path and path[0] == start and path[-1] == goal:
        return path
