import heapq

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star_search(start_pos, end_pos):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        came_from = {}
        frontier = [(0, start_pos)]
        cost_so_far = {start_pos: 0}

        while frontier:
            _, current = heapq.heappop(frontier)

            if current == end_pos:
                break

            for dr, dc in directions:
                next_pos = (current[0] + dr, current[1] + dc)
                if is_wall(next_pos):
                    continue

                new_cost = cost_so_far[current] + 1
                if next_pos not in cost_so_far or new_cost < cost_so_far[next_pos]:
                    cost_so_far[next_pos] = new_cost
                    priority = new_cost + heuristic(next_pos, end_pos)
                    heapq.heappush(frontier, (priority, next_pos))
                    came_from[next_pos] = current

        if end_pos not in came_from:
            return None

        path = [end_pos]
        while path[-1] != start_pos:
            path.append(came_from[path[-1]])
        path.reverse()
        return path

    if start == goal:
        return [start] if not is_wall(start) else []

    path_from_start = a_star_search(start, goal)
    if path_from_start:
        return path_from_start

    return []
