from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]):
        return []
    if goal[0] < 0 or goal[0] >= len(grid) or goal[1] < 0 or goal[1] >= len(grid[0]):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal_func, reverse=False):
        queue = deque([(start, [start])])
        visited = {start}
        while queue:
            pos, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == '.':
                    new_pos = (nc, nr) if reverse else (nr, nc)
                    new_path = path + [new_pos]
                    if goal_func(new_pos):
                        yield new_path
                    queue.append((new_pos, new_path))
                    visited.add((nr, nc) if not reverse else (nc, nr))

    def path_from_forward(path):
        return path

    def path_from_backward(path):
        return [ (g, r) for r, g in path[::-1] ]

    for path in bfs(start, lambda x: x in path_from_backward(bfs(goal, lambda y: y in path_from_forward([x]), reverse=True))):
        return path
    return []

