def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    from collections import deque

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    jump = set()

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def ibfs(pos, dir):
        x, y = pos
        dx, dy = dir
        nx, ny = x + dx, y + dy
        while is_valid(nx, ny):
            if (nx, ny) in jump:
                return (nx, ny)
            if (nx + dx, ny + dy) in jump or not is_valid(nx + dx, ny + dy):
                if not ((nx - x) % dx if dx != 0 else (ny - y) % dy):
                    jump.add((nx, ny))
            nx += dx
            ny += dy
        return (x, y)

    queue = deque(directions)
    visited = set()
    visited.add(start)
    prev = {start: None}

    while queue:
        pos, dir = queue.popleft()
        if pos in visited:
            continue
        visited.add(pos)
        if pos == goal:
            path = []
            while pos:
                path.append(pos)
                pos = prev[pos]
            return path[::-1]
        for d in directions:
            dx, dy = d
            np = ibfs((pos[0] + dx, pos[1] + dy), d)
            if np != pos and is_valid(np[0], np[1]):
                queue.append((np, d))
                if np not in prev:
                    prev[np] = pos
    return []
