import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.')) or \
       (not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.')):
        return []

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def heuristic(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    def a_star(start, goal, reverse=False):
        visited = set()
        pq = [(0, 0, start, [start])]
        min_g = {start: 0}

        while pq:
            _, g, current, path = heapq.heappop(pq)
            if current in visited:
                continue
            if current == goal:
                return path

            visited.add(current)
            h = heuristic(current, goal)
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                next_node = (nr, nc)
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    new_g = g + 1
                    if next_node not in min_g or new_g < min_g[next_node]:
                        min_g[next_node] = new_g
                        if reverse:
                            new_heuristic = heuristic(next_node, start)
                        else:
                            new_heuristic = heuristic(next_node, goal)
                        priority = new_g + new_heuristic
                        heapq.heappush(pq, (priority, new_g, next_node, path + [next_node]))
        return None

    forward_path = a_star(start, goal)
    backward_path = a_star(goal, start, reverse=True)

    if forward_path and backward_path:
        return forward_path
    elif forward_path:
        return forward_path
    elif backward_path:
        return backward_path[::-1]
    else:
        return []
