    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def a_star(start, goal, forward):
        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        pos_to_node = {start: start}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                return path[::-1] if path else None

            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if (0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and
                    grid[nr][nc] == '.'):
                    neighbor = (nr, nc)
                    if forward:
                        if not (current in pos_to_node and (nr, nc) in pos_to_node):
                            continue
                    else:
                        if not (current in pos_to_node and (nr, nc) in pos_to_node):
                            continue

                    tentative_g = g_score[current] + 1
                    if neighbor not in g_score or tentative_g < g_score[neighbor]:
                        came_from[neighbor] = current
                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return None

    forward_path = a_star(start, goal, True)
    reverse_path = a_star(goal, start, False)

    if not forward_path and not reverse_path:
        return []

    if forward_path:
        return forward_path
    else:
        return reverse_path[::-1]
