import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def is_wall(pos):
        r, c = pos
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def neighbors(pos):
        r, c = pos
        return [(r+dr, c+dc) for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]]  # orthogonal only

    def jump(pos, dir):
        r, c = pos
        dr, dc = dir
        new_r, new_c = r + dr, c + dc
        if not is_valid((new_r, new_c)):
            return None

        # Force move
        next_pos = (new_r, new_c)
        if is_valid(next_pos):
            # Check for forced neighbors
            for turn in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if turn != (dr, dc) and turn != (-dr, -dc):
                    tr, tc = new_r + turn[0], new_c + turn[1]
                    if is_wall((tr, tc)):
                        return next_pos

        # Continue jumping
        while True:
            new_r += dr
            new_c += dc
            if not is_valid((new_r, new_c)):
                return None
            if is_valid((new_r - dr, new_c - dc - dr * (dr != 0))):
                if is_wall((new_r - dr, new_c - dc - dr * (dr != 0))) or is_wall((new_r - dc * (dc != 0), new_c - dc - dr * (dr != 0))):
                    return (new_r, new_c)
            else:
                return None

    def get_successors(pos):
        succ = []
        for dir in [(-1,0), (1,0), (0,-1), (0,1)]:
            next_pos = pos[0] + dir[0], pos[1] + dir[1]
            if is_valid(next_pos):
                jump_pos = jump(next_pos, dir)
                if jump_pos:
                    succ.append(jump_pos)
        return succ

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    open_set = [(0, heuristic(start, goal), start)]
    visited = set()
    parent = {}

    while open_set:
        _, _, current = heapq.heappop(open_set)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)

        for next_pos in get_successors(current):
            if next_pos not in visited:
                parent[next_pos] = current
                heapq.heappush(open_set, (0, heuristic(next_pos, goal), next_pos))

    if goal not in parent and current != goal:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path if is_valid(start) and is_valid(goal) else []
