def solve(grid, start, goal):
    from collections import deque

    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def neighbors(r, c):
        moves = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        valid = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                valid.append((nr, nc))
        return valid

    # Jump Point Search for 4-connected grids
    def jps(grid, start, goal):
        def jump(r, c, dir):
            # Unpack direction
            dr, dc = dir
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            # Check for forced neighbor
            for fdir in neighbors(*dir):
                fnr, fnc = nr + fdir[0], nc + fdir[1]
                if is_valid(fnr, fnc) and (fnr, fnc) != (r, c) and not any(
                    (fnr + jdir[0], fnc + jdir[1]) == (r, c)
                    for jdir in [(0, 1), (1, 0), (0, -1), (-1, 0)] if jdir != (0, 0)
                ):
                    return nr, nc
            # Recursive jump if not on goal
            if (nr, nc) == goal:
                return nr, nc
            # Continue in direction
            return jump(nr, nc, dir)

        came_from = {}
        open_set = deque([start])
        open_set_set = {start}
        g_score = {start: 0}

        while open_set:
            current = open_set.popleft()
            open_set_set.remove(current)

            if current == goal:
                break

            for direction in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                next_point = jump(current[0], current[1], direction)
                if next_point:
                    nr, nc = next_point
                    new_g = g_score[current] + 1
                    if (nr, nc) not in g_score or new_g < g_score[(nr, nc)]:
                        g_score[(nr, nc)] = new_g
                        came_from[(nr, nc)] = current
                        if (nr, nc) not in open_set_set:
                            open_set.append((nr, nc))
                            open_set_set.add((nr, nc))

        if goal not in came_from:
            return []

        path = []
        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        return path[::-1]

    return jps(grid, start, goal)
