import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    for r, c in [start, goal]:
        if not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'):
            return []

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(pos):
        return abs(pos[0] - pos[1]) if isinstance(pos[1], int) else 0

    def a_star(start, goal, forward=True):
        def neighbors(pos):
            r, c = pos
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_free(nr, nc):
                    yield (nr, nc)

        class Node:
            def __init__(self, pos):
                self.pos = pos
                self.g = {pos: 0}
                self.f = {pos: heuristic(pos)}
                self.parent = {}
                self.frontier = [(self.f[pos], pos)]
                heapq.heapify(self.frontier)

            def pop(self):
                while self.frontier:
                    f, pos = heapq.heappop(self.frontier)
                    if pos not in self.g or f != self.f[pos]:
                        continue
                    return pos
                return None

            def expand(self, pos, other):
                r, c = pos
                g = self.g[pos] + 1
                for nr, nc in neighbors(pos):
                    if nr not in other.parent or g < other.g.get((nr, nc), float('inf')):
                        other.g[(nr, nc)] = g
                        other.f[(nr, nc)] = g + heuristic((nr, nc))
                        other.parent[(nr, nc)] = (r, c)
                        heapq.heappush(other.frontier, (other.f[(nr, nc)], (nr, nc)))

        if forward:
            source = Node(start)
            target = Node(goal)
        else:
            source = Node(goal)
            target = Node(start)

        while source.frontier:
            pos = source.pop()
            if pos in target.parent:
                # Reconstruct path from start to intersection and from intersection to goal
                path1 = [pos]
                while path1[-1] != start:
                    path1.append(source.parent[path1[-1]])
                path1.reverse()

                path2 = [pos]
                while path2[-1] != goal:
                    path2.append(target.parent[path2[-1]])
                return path1 + path2

            source.expand(pos, source if forward else target)

            pos = target.pop()
            if pos in source.parent:
                # Reconstruct path from start to intersection and from intersection to goal
                path1 = [pos]
                while path1[-1] != start:
                    path1.append(source.parent[path1[-1]])
                path1.reverse()

                path2 = [pos]
                while path2[-1] != goal:
                    path2.append(target.parent[path2[-1]])
                return path1 + path2

            target.expand(pos, target if forward else source)

        return None

    path = a_star(start, goal)
    if path:
        return path
    return []
