            for direction in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + direction[0], c + direction[1]
                if (nr != r + dr or nc != c + dc) and not is_wall(nr, nc):
                    jump_pos = jump(nr, nc, direction[0], direction[1], r, c)
                    if jump_pos:
