    frontier = [(0, 0, start, None, None)]
    heapq.heapify(frontier)
    came_from = {}
    cost = {start: 0}

    while frontier:
        _, _, (r, c), pr, pc = heapq.heappop(frontier)
        if (r, c) == goal:
            break
        for dr, dc in dirs:
            if dr == 0 and dc == 0:
                continue
            if abs(dr) == 1 and pr is not None and pr == r - dr and pc == c - dc:
                continue
            if abs(dc) == 1 and pc is not None and pc == c - dc and pr == r - dr:
                continue
            nr, nc = r, c
