            while True:
                nr += dr
                nc += dc
                if not (0 <= nr < len(grid) and 0 <= nc < len(grid[0])):
                    break
                if grid[nr][nc] == '#':
                    break
                if nr == pr0 and nc == pc0:
                    break
            if (nr - dr, nc - dc) == (pr0, pc0):
                pass
            else:
                pr0 = pr
                pc0 = pc
            if (nr - dr, nc - dc) == (r, c):
                continue
            if (nr - dr, nc - dc) not in came_from or cost[(r, c)] + 1 < cost[(nr - dr, nc - dc)]:
                came_from[(nr - dr, nc - dc)] = (r, c)
                cost[(nr - dr, nc - dc)] = cost[(r, c)] + 1
                h = abs(nr - dr - goal[0]) + abs(nc - dc - goal[1])
