        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                break
            for dx, dy in directions:
                if forward:
                    next_node = (current[0] + dx, current[1] + dy)
                else:
                    next_node = (current[0] - dx, current[1] - dy)
                if (0 <= next_node[0] < len(grid) and 0 <= next_node[1] < len(grid[0]) and
                    grid[next_node[0]][next_node[1]] == '.'):
                    tentative_g = g_score[current] + 1
                    if next_node not in g_score or tentative_g < g_score[next_node]:
                        came_from[next_node] = current
                        g_score[next_node] = tentative_g
                        f_score[next_node] = tentative_g + heuristic(next_node, goal)
                        heapq.heappush(open_set, (f_score[next_node], next_node))

        if goal not in came_from:
            return {}
        path = []
        current = goal
        while current in came_from:
            path.append(current)
            current = came_from[current]
        path.append(start)
        return path[::-1]

    path_forward = a_star_search(start, goal, forward=True)
    path_backward = a_star_search(goal, start, forward=False)

    if not path_forward and not path_backward:
        return []
    elif not path_forward:
