def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_wall(pos):
        r, c = pos
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def heuristic(pos, end):
        r1, c1 = pos
        r2, c2 = end
        return abs(r1 - r2) + abs(c1 - c2)

    def a_star(front, start, end, came_from, cost_so_far, other_came_from):
        frontier = [(0, front)]
        heapq.heapify(frontier)
        while frontier:
            _, pos = heapq.heappop(frontier)
            if pos in other_came_from:
                path = []
                p = pos
                while p in came_from:
                    path.append(p)
                    p = came_from[p]
                path.reverse()
                p = other_came_from[pos]
                while p != end:
                    path.append(p)
                    p = other_came_from[p]
                return path
            if pos in cost_so_far:
                continue
            cost_so_far[pos] = 0
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = pos[0] + dr, pos[1] + dc
                next_pos = (nr, nc)
                if is_wall(next_pos):
                    continue
                if next_pos not in cost_so_far:
                    came_from[next_pos] = pos
                    cost_so_far[next_pos] = cost_so_far[pos] + 1
                    priority = cost_so_far[next_pos] + heuristic(next_pos, end)
                    heapq.heappush(frontier, (priority, next_pos))
        return None

    came_from1 = {}
    cost_so_far1 = {}
    came_from2 = {}
    cost_so_far2 = {}
    forward_path = a_star(start, start, goal, came_from1, cost_so_far1, came_from2)
    backward_path = a_star(goal, goal, start, came_from2, cost_so_far2, came_from1)

    if forward_path is not None:
        return forward_path
    return []
