def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(source, target):
        came_from = {}
        cost_so_far = {}
        q = [(heuristic(source, target), 0, source)]
        while q:
            _, steps, current = heapq.heappop(q)
            if current in cost_so_far and cost_so_far[current] < steps:
                continue
            if current == target:
                break
            cost_so_far[current] = steps
            for next in neighbors(current):
                new_steps = steps + 1
                if next not in cost_so_far:
                    heapq.heappush(q, (new_steps + heuristic(next, target), new_steps, next))
                    came_from[next] = current
        return came_from

    forward_came_from = a_star(start, goal)
    backward_came_from = a_star(goal, start)

    def merge_paths(c1, c2):
        path1 = [c1]
        while c1 in forward_came_from:
            c1 = forward_came_from[c1]
            path1.append(c1)
        path2 = [c2]
        while c2 in backward_came_from:
            c2 = backward_came_from[c2]
            path2.append(c2)
        pos = path1[-1]
        while pos in path2:
            path2.remove(pos)
        path = path2 + path1
        if path[0] == goal:
            path.reverse()
        return path

    for node in forward_came_from:
        if node in backward_came_from:
            path = merge_paths(node, node)
            if path[0] == start and path[-1] == goal:
                return path
    return []

def is_free(grid, pos):
    row, col = pos
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'
