            next_cell = (nr, nc)
            if not is_wall(nr, nc) and next_cell not in visited:
                visited.add(next_cell)
                result = dfs(limit, next_cell, path + [next_cell], visited)
                if result is not None:
                    return result
                visited.remove(next_cell)
        return None

    def iddfs():
        depth = 0
        visited = set([start])
        while True:
            result = dfs(depth, start, [start], visited.copy())
            if result is not None:
                return result
            if depth > rows * cols:
