        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == '.':
                yield (nr, nc)

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, forward=True):
        open_set = [(heuristic(start, goal), start)]
        came_from = {}
        cost_so_far = {start: 0}
        goal_found = False

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                goal_found = True
                break
            for next_cell in neighbors(current):
                new_cost = cost_so_far[current] + 1
                if next_cell not in cost_so_far or new_cost < cost_so_far[next_cell]:
                    cost_so_far[next_cell] = new_cost
                    priority = new_cost + heuristic(next_cell, goal if forward else start)
                    heapq.heappush(open_set, (priority, next_cell))
                    came_from[next_cell] = current
        if goal_found:
            path = []
            current = goal if forward else start
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.reverse()
            return path
        return None

    forward_path = a_star(start, goal, forward=True)
    backward_path = a_star(goal, start, forward=False)

    if forward_path:
        return [start] + forward_path
    if backward_path:
        return backward_path + [goal]
    return []

def is_free(grid, pos):
