def solve(grid, start, goal):
    if start == goal:
        return [start]

    start_row, start_col = start
    goal_row, goal_col = goal

    if (not (0 <= start_row < len(grid) and 0 <= start_col < len(grid[0])) or
        not (0 <= goal_row < len(grid) and 0 <= goal_col < len(grid[0]))):
        return []

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    dirs_name = {(-1,0): 'up', (1,0): 'down', (0,-1): 'left', (0,1): 'right'}

    def get_neighbors(node):
        row, col = node
        neighbors = []
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if (0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and
                grid[new_row][new_col] == '.'):
                neighbors.append((new_row, new_col))
        return neighbors

    def is_corner(pos, next_pos, dir):
        d = dir
        r, c = pos
        rn, cn = next_pos
        if (abs(r - rn), abs(c - cn)) == (1, 1):
            if d == 'up' and grid[r - 1][c] == '.' and grid[r][c + 1] == '#':
                return True
            elif d == 'down' and grid[r + 1][c] == '.' and grid[r][c + 1] == '#':
                return True
            elif d == 'left' and grid[r][c - 1] == '.' and grid[r + 1][c] == '#':
                return True
            elif d == 'right' and grid[r][c + 1] == '.' and grid[r + 1][c] == '#':
                return True
        return False

    def jump(pos, dir):
        r, c = pos
        dr, dc = dir
        next_r, next_c = r + dr, c + dc
        if not (0 <= next_r < len(grid) and 0 <= next_c < len(grid[0])):
            return None
        if grid[next_r][next_c] == '#':
            return None

        if dir[0] or dir[1]:  # Not diagonal
            if dir[0]:  # Vertical
                if grid[r][c + 1] == '#':
                    return (next_r, next_c)
                if (grid[next_r][c + 1] == '.' and
                    (grid[next_r + dr][c + dc] == '#' if next_r + dr < len(grid) else True)):
                    return (next_r, next_c)
            else:  # Horizontal
                if grid[r + 1][c] == '#':
                    return (next_r, next_c)
                if (grid[next_r + 1][c] == '.' and
                    (grid[next_r + dr][c + dc] == '#' if next_r + dr < len(grid) else True)):
                    return (next_r, next_c)
        return jump((next_r, next_c), dir)

    def search(node, dir, goal):
        row, col = node
        g, h = node[2], node[3]
        while True:
            dr, dc = dir
            next_r, next_c = row + dr, col + dc
            if not (0 <= next_r < len(grid) and 0 <= next_c < len(grid[0])):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if grid[next_r][next_c] == '#':
                return None
            if is_corner((row, col), (next_r, next_c), dirs_name[dir]):
                next_node = jump((next_r, next_c), dir)
                if next_node:
                    return next_node
                else:
                    return None
            row, col = next_r, next_c

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    visited = set()
    pq = [(0, 0, start, (0, 0), ())]
    heapq.heapify(pq)

    while pq:
        f, g, pos, dir, path = heapq.heappop(pq)
        if pos in visited:
            continue
        visited.add(pos)
        path = path + (pos,)
        if pos == goal:
            return list(path)
        for ndir in directions:
            next_pos = jump(pos, ndir) if ndir != (0, 0) else search((g, 0, pos, 0, path), ndir, goal)
            if next_pos and next_pos not in visited:
                new_g = g + 1
                new_h = heuristic(next_pos, goal)
                new_f = new_g + new_h
                heapq.heappush(pq, (new_f, new_g, next_pos, ndir, path))

    return []
