def solve(grid, start, goal):
    from collections import deque

    HEIGHT = len(grid)
    WIDTH = len(grid[0]) if HEIGHT > 0 else 0

    def is_valid(row, col):
        return 0 <= row < HEIGHT and 0 <= col < WIDTH and grid[row][col] == '.'

    def get_neighbors(point):
        row, col = point
        neighbors = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if is_valid(r, c):
                neighbors.append((r, c))
        return neighbors

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path = [current] + total_path
        return total_path

    def jump(row, col, dir_r, dir_c, came_from, open_set, closed_set):
        r, c = row + dir_r, col + dir_c
        if not is_valid(r, c):
            return None

        if (r, c) == goal:
            return (r, c)

        neighbors = []
        if dir_r != 0 and dir_c != 0:
            neighbors = [ (r + dr, c + dc) for dr, dc in [ (1, 0), (-1, 0), (0, 1), (0, -1) ]
                        if is_valid(r + dr, c + dc) and (r + dr == row or c + dc == col) ]
        elif dir_r != 0:
            neighbors = [ (r + 1, c), (r - 1, c) ] if is_valid(r + 1, c) or is_valid(r - 1, c) else []
        else:
            neighbors = [ (r, c + 1), (r, c - 1) ] if is_valid(r, c + 1) or is_valid(r, c - 1) else []

        forced_neighbors = [ (nr, nc) for nr, nc in neighbors
                            if not is_valid(nr + dir_r, nc + dir_c) and is_valid(nr, nc) ]

        for n in forced_neighbors:
            if n not in closed_set:
                if n not in came_from or len(reconstruct_path(came_from, n)) > len(reconstruct_path(came_from, (r, c))):
                    came_from[n] = (r, c)
                    open_set.append(n)

        if not forced_neighbors:
            return None
        return (r, c)

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    came_from = {}
    open_set = deque([start])
    closed_set = set([start])

    while open_set:
        current = open_set.popleft()
        closed_set.add(current)

        if current == goal:
            return reconstruct_path(came_from, current)

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_node = (current[0] + dr, current[1] + dc)
            if is_valid(*next_node):
                if (next_node not in closed_set):
                    came_from[next_node] = current
                    open_set.append(next_node)
                    jump_result = jump(current[0], current[1], dr, dc, came_from, open_set, closed_set)
                    if jump_result and jump_result not in closed_set:
                        came_from[jump_result] = current
                        open_set.append(jump_result)

    return []
