            if current == goal:
                return reconstruct_path(came_from, start, current)

            for dr, dc in directions:
                next_pos = (current[0] + dr, current[1] + dc)
                if is_wall(next_pos) or next_pos in g_score:
                    continue
                tentative_g = g_score[current] + 1
                if not is_free(next_pos):
                    continue
                came_from[next_pos] = current
                g_score[next_pos] = tentative_g
                f_score[next_pos] = tentative_g
                dir_map[next_pos] = dir_to_index[(dr, dc)]
                heapq.heappush(open_set, (f_score[next_pos], next_pos, dir_to_index[(dr, dc)]))
                if is_jump_point(next_pos, dir_to_index[(dr, dc)]):
                    heapq.heappush(open_set, (f_score[next_pos], next_pos, dir_to_index[(dr, dc)]))
        return []

