        dr, dc = directions[dir_idx]
        r, c = pos

        next_pos = (r + dr, c + dc)
        if is_wall(next_pos):
            return False

        new_dir_idx = dir_to_index[(dr, dc)]

        if dir_idx == 0 or dir_idx == 1:  # Vertical
            up = (r - 1, c)
            down = (r + 1, c)
            l, r_cell = (r, c - 1), (r, c + 1)
            if is_free(up) and is_free(r_cell) and is_free(l):
                return True
            if is_free(down) and is_free(r_cell) and is_free(l):
                return True
        else:  # Horizontal
            left = (r, c - 1)
            right = (r, c + 1)
            up, down = (r - 1, c), (r + 1, c)
            if is_free(left) and is_free(up) and is_free(down):
                return True
            if is_free(right) and is_free(up) and is_free(down):
                return True

        if is_free((r + dr, c + dc)):
            if is_jump_point((r + dr, c + dc), new_dir_idx):
                return True
        return False

    def reconstruct_path(came_from, start, current):
        path = []
        while current != start:
            path.append(current)
            current = came_from[current]
        path.reverse()
        path.insert(0, start)
        return path

    if not is_free(start) or not is_free(goal):
        return []
    if start == goal:
        return [start]

