def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows = len(grid)
    cols = len(grid[0])

    # Check if start or goal is a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    # Check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'  # Must be free

    # Jump Point Search (JPS) utility functions
    def get_neighbors(r, c, came_from):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (dr, dc) != came_from:
                neighbors.append((nr, nc, dr, dc))
        return neighbors

    def prune(r, c, dir_r, dir_c):
        # Check if a forced neighbor exists -> prunes the search direction
        if grid[r + dir_r][c + dir_c] != '.':  # Not a free cell, we cannot continue
            return []
        pruned = []
        if dir_r == 0:  # Horizontal (left or right)
            for rd in [-1, 1]:
                if is_valid(r + rd, c + dir_c):
                    if not is_valid(r + rd, c) or not is_valid(r, c + dir_c):
                        return [(r + rd, c + dir_c, 0, 0)]  # A forced neighbor
        elif dir_c == 0:  # Vertical (up or down)
            for cd in [-1, 1]:
                if is_valid(r + dir_r, c + cd):
                    if not is_valid(r, c + cd) or not is_valid(r + dir_r, c):
                        return [(r + dir_r, c + cd, 0, 0)]  # A forced neighbor
        else:  # Diagonal
            # Check if a corner can be cut (i.e., at least one free cell in a diagonal path)
            if not is_valid(r + dir_r, c) or not is_valid(r, c + dir_c):
                return [(r + dir_r, c, 0, 0), (r, c + dir_c, 0, 0)]
        # No forced neighbor, just extend the search
        return [(r + dir_r, c + dir_c, dir_r, dir_c)]

    # JPS main search function
    from collections import deque

    visited = set()
    path = {}
    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # (pos_r, pos_c, came_from_dir_r, came_from_dir_c)

    while queue:
        r, c, came_from_dr, came_from_dc = queue.popleft()
        current = (r, c)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)

        neighbors = prune(r, c, came_from_dr, came_from_dc)
        for nr, nc, dr, dc in neighbors:
            if (nr, nc) not in visited:
                path[(nr, nc)] = current
                queue.append((nr, nc, dr, dc))

    # If no path found
    if goal not in path:
        return []

    # Reconstruct path from goal to start
    result = []
    current = goal
    while current != start:
        result.append(current)
        current = path[current]
    result.append(start)
    return result[::-1]
