        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, reversed=False):
        frontier = []
        heapq.heappush(frontier, (0, start))
        came_from = {}
        cost_so_far = {start: 0}

        while frontier:
            _, current = heapq.heappop(frontier)

            if current == goal:
                break

            for dr, dc in directions:
                r, c = current
                nr, nc = (r + dr, c + dc) if not reversed else (r - dr, c - dc)
                next_cell = (nr, nc)
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    new_cost = cost_so_far[current] + 1
                    if next_cell not in cost_so_far or new_cost < cost_so_far[next_cell]:
                        cost_so_far[next_cell] = new_cost
                        priority = new_cost + heuristic(next_cell, goal)
                        heapq.heappush(frontier, (priority, next_cell))
                        came_from[next_cell] = current

        return came_from

    came_from_forward = a_star(start, goal, reversed=False)
    came_from_backward = a_star(goal, start, reversed=True)

    shared_nodes = set(came_from_forward.keys()) & set(came_from_backward.keys())
    if not shared_nodes:
        return []

    def reconstruct_path(intermediate):
        path = []
        current = intermediate
        while current in came_from_forward:
            path.append(current)
            current = came_from_forward[current]
        path.reverse()
        current = intermediate
        while current in came_from_backward:
            next_node = came_from_backward[current]
            if next_node != path[-1]:
                path.append(next_node)
                current = next_node
        if path and path[0] == start:
            return path
        return []

    path = None
    min_len = float('inf')
    for node in shared_nodes:
        p = reconstruct_path(node)
        if p and len(p) < min_len:
            path = p
            min_len = len(p)

    if path and path[0] == start and path[-1] == goal:
        return path
    return []

