        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def search_dir(r, c, dr, dc):
        if is_wall(r + dr, c + dc):
            return None
        while True:
            r += dr
            c += dc
            if is_wall(r, c):
                return (r - dr, c - dc)
            if (dr == 0 or is_wall(r, c - dc)) and (dc == 0 or is_wall(r - dr, c)):
                return (r, c)

    def find_jump_points(r, c, pr, pc):
        jump_points = []
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            if is_wall(r + dr, c + dc):
                continue
            if (pr is not None and pr != r + dr) or (pc is not None and pc != c + dc):
                jr, jc = search_dir(r, c, dr, dc)
                if jr is not None:
                    jump_points.append((jr, jc))
        return jump_points

    def reconstruct_path(came_from, current):
        path = []
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            path_list = [current]
            while current in came_from:
                current = came_from[current]
                path_list.append(current)
            return path_list[::-1]

        for np in find_jump_points(*current, *came_from[current] if current in came_from else (None, None)):
            if np not in g_score:
                g_score[np] = g_score[current] + 1
                came_from[np] = current
                heapq.heappush(open_set, (g_score[np], np))

    return []

