def solve(grid, start, goal):
    if start == goal:
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols)) or \
       (not (0 <= goal[0] < rows and 0 <= goal[1] < cols)) or \
       grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = [(start, [start])]

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def is_empty(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump(r, c, dr, dc):
        if is_wall(r, c):
            return None
        if (r, c) == goal:
            return (r, c)

        # Check if current is jump point
        # Force check for forced neighbors in diagonals is not required for 4-way movement
        candidates = []
        for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if ndr != dr or ndc != dc:
                nr, nc = r + ndr, c + dc
                if is_empty(nr, nc) and not is_empty(r + dr, nc):
                    candidates.append(jump(nr, nc, ndr, ndc))

        for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if ndr != dr or ndc != dc:
                nr, nc = r + dr + ndr, c + dc + ndc
                if is_empty(r + dr, nc) and not is_empty(nr, nc):
                    candidates.append(jump(r + dr, nc, dr, dc))

        for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + 2*dr + ndr, c + 2*dc + ndc
            if is_empty(r + dr, c + dc) and not is_empty(nr, nc):
                if (ndr, ndc) == (0, 0):
                    continue
                candidates.append(jump(r + dr, c + dc, ndr, ndc))

        for cand in candidates:
            if cand:
                return cand

        if not is_empty(r + 2*dr, c + 2*dc) and is_empty(r + dr, c + dc):
            return jump(r + dr, c + dc, dr, dc)

        if is_empty(r + dr, c + dc) and not (is_empty(r + dr, c) and is_empty(r, c + dc)):
            next_pos = (r + dr, c + dc)
            return jump(next_pos[0], next_pos[1], dr, dc)
        return None

    def jps_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            j = jump(r, c, dr, dc)
            if j and j != (r, c) and is_empty(j[0], j[1]):
                neighbors.append(j)
        return neighbors

    while queue:
        (pos, path) = queue.pop(0)
        if pos == goal:
            return path
        if pos in visited:
            continue
        visited.add(pos)
        for next_pos in jps_neighbors(pos[0], pos[1]):
            if next_pos not in visited:
                queue.append((next_pos, path + [next_pos]))
    return []
