            (is_in_bounds((r, c - 1)) and is_passable((r, c - 1))) or
            get_jump_point((next_r, next_c), (0, dc), visited)):
            return get_jump_point((next_r, next_c), (dr, dc), visited)
        elif (dr != 0 or dc != 0) and (get_jump_point((next_r, next_c), (dr, dc), visited) is None):
