                    elif res is None:
                        break
                    else:
                        nr, nc = res
        return []

    def reconstruct_path(parent, start, goal):
        path = [goal]
        current = goal
        while current != start:
            current = parent.get(current)
            if current is None:
                return []
            path.append(current)
        path.reverse()
        return path

    return jps_search()
