        came_from = {}

        g_score = {start: 0} if not reverse else {goal: 0}
        f_score = {start: heuristic(start, goal)} if not reverse else {goal: heuristic(start, goal)}
        goal_point = goal if not reverse else start

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal_point:
                path = []
