                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                    neighbor = (nx, ny)
                    tentative_g = g_score[current] + 1

                    if reverse and neighbor not in f_score:
                        f_score[neighbor] = 0
                    if neighbor not in g_score or tentative_g < g_score[neighbor]:
                        came_from[neighbor] = current
                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + heuristic(neighbor, goal_point)
                        heapq.heappush(open_set, (f_score[neighbor], neighbor))
        return None

    def bidirectional_a_star():
        path1 = a_star(False)
        path2 = a_star(True)
        if path1 is not None:
            return path1
        if path2 is not None:
            return path2

        forward_frontier = set([start])
        backward_frontier = set([goal])
        forward_set = set([start])
        backward_set = set([goal])

