            backward_vertices = expand_direction(True, start, backward_came_from, backward_vertices or backward_frontier, forward_set)
            forward_frontier = forward_vertices
            backward_frontier = backward_vertices
            forward_set.update(forward_vertices)
            backward_set.update(backward_vertices)

            if backward_frontier.intersection(forward_set):
                intersection = backward_frontier.intersection(forward_set)
                for n in intersection:
