                        c1 = forward_came_from[c1]
                    while c2 is not None:
                        path_backward.append(c2)
                        c2 = backward_came_from[c2]
                    path = path_forward[:-1] + path_backward[::-1]
                    return path

        return []

    path = bidirectional_a_star()
    if path and path[0] == start and path[-1] == goal:
        return path
    return []
