            nr, nc = r + dr, c + dc
            if not is_valid((nr, nc)):
                return None

            if (dr, dc) != (came_from_dr, came_from_dc):
                if is_corner(r, c, dr, dc):
                    return (nr, nc)
            else:
                if is_corner(r, c, -dr, dc):
                    return (nr, nc)
                if is_corner(r, c, dr, -dc):
