            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.reverse()
                return [start] + path

            for ddr, ddc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = current[0] + ddr, current[1] + ddc
                if is_valid((nr, nc)) and (nr, nc) not in came_from:
