                        if jump not in cost or cost[jump] > cost[current] + 1:
                            cost[jump] = cost[current] + 1
                            came_from[jump] = current
                            queue.append((cost[jump] + h, jump, ddr, ddc))

        return []

    path = jps_search(start, goal)
    return path if path and path[-1] == goal else []
