        # Check diagonal jump possibilities
        if dr != 0 and dc != 0:
            if is_valid(r, c - dc) or is_valid(r - dr, c):
                if is_valid(r, c - dc):
                    if jump(r, c - dc, (dr, -dc), goal) is not None:
                        return (r, c)
                if is_valid(r - dr, c):
                    if jump(r - dr, c, (dr, dc), goal) is not None:
                        return (r, c)
        # Check straight jump possibilities
        if is_valid(r, c - dc) or is_valid(r - dr, c):
            while True:
                r += dr
                c += dc
                if not is_valid(r, c):
                    return None
                if (r, c) == goal:
                    return (r, c)
                if is_valid(r, c - dc) or is_valid(r - dr, c):
                    break
        return (r, c)

    def jump_point_search(start, goal):
        if not is_valid(*start) or not is_valid(*goal):
            return []

        queue = [(0, 0, start, None)]
        heapq.heapify(queue)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
