                        dir2 = sum(d)
                        next_dir = get_direction(current, (current[0] + d[0] * dir2, current[1] + d[1] * dir2))
                        jump_point = jump(current[0] + d[0], current[1] + d[1], next_dir, goal)
                        if jump_point and jump_point not in g_cost:
                            g = g_cost[current] + 1
                            g_cost[jump_point] = g
                            heapq.heappush(queue, (g + abs(jump_point[0] - goal[0]) + abs(jump_point[1] - goal[1]), g, jump_point, next_dir))
                            came_from[jump_point] = current
