    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Build obstacle map
    obstacle = [[grid[r][c] == '#' for c in range(cols)] for r in range(rows)]

    # Jump Point Search Algorithm
    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not obstacle[nr][nc]:
                neighbors.append((nr, nc))
        return neighbors

    def jump(r, c, dirr, dirc, came_from):
        if not is_valid(r, c) or (r, c) == came_from:
            return None
        if (r, c) == goal:
            return (r, c)
        found = False
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if (dr, dc) != dirr, dirc and (nr, nc) == came_from:
                continue
            if is_valid(nr, nc):
                found = True
                break
        if not found:
            return None
        if dirr, dirc == (0, 1) or dirr, dirc == (0, -1):
            for up in (-1, 0, 1):
                for right in (0, 1):
                    nr, nc = r + up, c + right
                    if (up, right) == (0, 0):
                        continue
                    if is_valid(nr, nc):
                        return jump(nr, nc, dirr, dirc, (r, c))
        elif dirr, dirc == (1, 0) or dirr, dirc == (-1, 0):
            for up in (0, 1):
                for left in (-1, 0, 1):
                    if (up, left) == (0, 0):
                        continue
                    nr, nc = r + up, c + left
                    if is_valid(nr, nc):
                        return jump(nr, nc, dirr, dirc, (r, c))
        return jump(r + dirr, c + dirc, dirr, dirc, (r, c))

    def get_successors(pos, came_from=None):
        r, c = pos
        successors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols or obstacle[nr][nc]:
                continue
            if (dr, dc) == (0, 1) or (dr, dc) == (0, -1):
                for up in (-1, 0, 1):
                    for right in (0, 1):
                        if (up, right) != (0, 0):
                            nrr, ncc = nr + up, nc + right
                            if is_valid(nrr, ncc) and (nrr, ncc) != (r, c):
                                successors.append((nrr, ncc))
            elif (dr, dc) == (1, 0) or (dr, dc) == (-1, 0):
                for up in (0, 1):
                    for left in (-1, 0, 1):
                        if (up, left) != (0, 0):
                            nrr, ncc = nr + up, nc + left
                            if is_valid(nrr, ncc) and (nrr, ncc) != (r, c):
                                successors.append((nrr, ncc))
        return successors

    open_set = [(heuristic(start, goal), heuristic(start, goal), start)]
    cost = {start: 0}
    came_from = {}

    while open_set:
        _, _, current = heapq.heappop(open_set)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return path[::-1]

        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or obstacle[nr][nc]:
                continue
            if (nr, nc) not in came_from or jump(nr, nc, dr, dc, current) is not None:
                next_pos = jump(nr, nc, dr, dc, current)
                if next_pos is None:
                    continue
                if next_pos == goal:
                    came_from[next_pos] = current
                    break
                if next_pos not in cost or cost[next_pos] > cost[current] + 1:
                    cost[next_pos] = cost[current] + 1
                    heapq.heappush(open_set, (cost[current] + 1 + heuristic(next_pos, goal), heuristic(next_pos, goal), next_pos))
                    came_from[next_pos] = current

    return []
