            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.append(current)
                return list(reversed(path)) if grid_forward else path
            if current in closed_set:
                continue
            closed_set.add(current)
            for neighbor in get_neighbors(current):
                if neighbor not in came_from and neighbor not in closed_set:
                    came_from[neighbor] = current
                    heapq.heappush(open_set, (heuristic(neighbor, goal), neighbor))
        return None

    path_a = a_star(start, goal, True)
    path_b = a_star(goal, start, False)
    if not path_a or not path_b:
        return []

    common_nodes = set(path_a).intersection(path_b)
    for node in common_nodes:
        path1 = path_a[:path_a.index(node) + 1]
        path2 = path_b[:path_b.index(node)][::-1]
