from heapq import heappush, heappop

def solve(grid, start, goal):
    def is_wall(pos):
        row, col = pos
        return row < 0 or col < 0 or row >= len(grid) or col >= len(grid[0]) or grid[row][col] == '#'

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    if is_wall(start) or is_wall(goal):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    def a_star(start, goal, forward=True):
        visited = {}
        open_set = []
        heappush(open_set, (manhattan(start, goal), 0, start, None))
        while open_set:
            _, cost, curr, prev = heappop(open_set)
            if curr in visited:
                continue
            visited[curr] = prev
            if curr == goal:
                break
            for dr, dc in dirs:
                next_ = (curr[0]+dr, curr[1]+dc)
                if not is_wall(next_) and next_ not in visited:
                    heappush(open_set, (manhattan(next_, goal) + cost + 1, cost + 1, next_, curr))
        return visited

    forward_path = a_star(start, goal, forward=True)
    backward_path = a_star(goal, start, forward=False)

    if start not in forward_path or goal not in backward_path:
        return []

    forward_set = set(forward_path)
    backward_set = set(backward_path)
    intersection = forward_set & backward_set

    def get_path(from_dict, from_pos, to_pos):
        path = []
        while from_pos != to_pos:
            path.append(from_pos)
            from_pos = from_dict[from_pos]
        path.append(to_pos)
        return path

    min_path = None
    min_len = float('inf')

    for meet in intersection:
        fpath = get_path(forward_path, start, meet)
        bpath = get_path(backward_path, goal, meet)
        bpath.reverse()
        full_path = fpath + bpath[1:]
        if len(full_path) < min_len:
            min_len = len(full_path)
            min_path = full_path

    if min_path and all(grid[row][col] == '.' for row, col in min_path):
        return min_path
    return []
