def solve(grid, start, goal):
    # Check if start or goal is a wall
    if (is_wall(grid, start) or is_wall(grid, goal)):
        return []

    # If start is already the goal
    if start == goal:
        return [start]

    # JPS main logic
    neighbors = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_wall(point):
        (r, c) = point
        return r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == '#'

    def jump(r, c, dr, dc, came_from):
        if is_wall((r, c)):
            return None
        if (r, c) == goal:
            return (r, c)

        for (ndr, ndc) in [(0, -1), (-1, 0), (1, 0), (0, 1)]:
            if ndr != -dr and ndc != -dc and ndr != dr and ndc != dc:
                if not is_wall((r + ndr, c + ndc)):
                    result = jump(r + dr, c + dc, dr, dc, (r, c))
                    if result:
                        return result

        if dr or dc:
            if not is_wall((r + dr, c)) and (r + dr, c) != came_from and (r + dr, c) != came_from:
                result = jump(r + dr, c + dc, dr, dc, (r, c))
                if result:
                    return result
            if not is_wall((r, c + dc)) and (r, c + dc) != came_from and (r, c + dc) != came_from:
                result = jump(r + dr, c + dc, dr, dc, (r, c))
                if result:
                    return result
        return None

    def bfs():
        from collections import deque

        visited = set()
        queue = deque([(start, [])])

        while queue:
            (pos, path) = queue.popleft()
            if pos == goal:
                return path + [pos]
            if pos in visited:
                continue
            visited.add(pos)
            for (dr, dc) in neighbors:
                next_pos = (pos[0] + dr, pos[1] + dc)
                if not is_wall(next_pos) and next_pos not in visited:
                    j = jump(next_pos[0], next_pos[1], dr, dc, pos)
                    if j:
                        queue.append((j, path + [pos]))
        return []

    return bfs()
