        return []
    if start == goal:
        return [start]

    directions = [(0, 1, 'r'), (1, 0, 'd'), (0, -1, 'l'), (-1, 0, 'u')]
    direction_remap = {'r': (0, 1), 'd': (1, 0), 'l': (0, -1), 'u': (-1, 0)}

    def is_wall(r, c):
        return r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == '#'

    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def jump(r, c, dr, dc, came_from):
        if is_wall(r, c):
            return None

        neighbors = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        for nr, nc in neighbors:
            if (nr, nc) == (-dr, -dc):
                continue
            if (0 <= r + nr < len(grid)) and (0 <= c + nc < len(grid[0])):
                if not is_wall(r + nr, c + nc) and (r + nr, c + nc) != came_from:
                    return (r, c)

        next_r, next_c = r + dr, c + dc
        if jump(next_r, next_c, dr, dc, (r, c)) is not None:
            return (r, c)
        return None

    def get_neighbors(r, c, dir):
        if dir is None:
            return [(r + dr[0], c + dr[1]) for dr in directions]
        dr, dc = direction_remap.get(dir, (0, 0))
        new_r, new_c = r + dr, c + dc
        if not is_wall(new_r, new_c):
            return [jump(new_r, new_c, dr, dc, (r, c))] if jump(new_r, new_c, dr, dc, (r, c)) else []
        return []

    visited = set()
    pq = [(0, start[0], start[1], None)]
    prev = {}

    while pq:
        _, r, c, dir = heapq.heappop(pq)
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for nr, nc in get_neighbors(r, c, dir):
            if (nr, nc) not in visited and not is_wall(nr, nc):
                prev[(nr, nc)] = (r, c)
                priority = heuristic((nr, nc))
                heapq.heappush(pq, (priority, nr, nc, dir))

    if goal not in prev:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = prev[curr]
    path.append(start)
    return path[::-1]
