import heapq

def solve(grid, start, goal):
    if is_wall(grid, start[0], start[1]) or is_wall(grid, goal[0], goal[1]):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def get_neighbors(pos):
        r, c = pos
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        return [(r + dr, c + dc) for dr, dc in directions if not is_wall(r + dr, c + dc)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump(r, c, dr, dc, visited):
        if is_wall(r, c):
            return None
        if (r, c) in visited:
            return None
        if (r, c) == goal:
            return (r, c)
        visited.add((r, c))

        next_r, next_c = r + dr, c + dc
        if is_wall(next_r, next_c):
            return None

        if dr != 0 and dc != 0:  # diagonal move, not needed for 4-directional movement
            return None

        if dr != 0:
            for new_dc in [-1, 1]:
                if not is_wall(r + dr, c + new_dc) and jump(r + dr, c + new_dc, dr, new_dc, visited) is not None:
                    return (r, c)
        elif dc != 0:
            for new_dr in [-1, 1]:
                if not is_wall(r + new_dr, c + dc) and jump(r + new_dr, c + dc, dr, dc, visited) is not None:
                    return (r, c)

        return jump(next_r, next_c, dr, dc, visited)

    def successors(pos):
        r, c = pos
        result = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            visited = set()
            jump_r, jump_c = jump(r, c, dr, dc, visited)
            if jump_r is not None and jump_c is not None:
                result.append((jump_r, jump_c))
        return result

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    open_set = []
    heapq.heappush(open_set, (0, start))
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}
    came_from = {}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)
        for neighbor in successors(current):
            tentative_g = g_score[current] + 1
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []
