    def heuristic(pos, target):
        r1, c1 = pos
        r2, c2 = target
        return abs(r1 - r2) + abs(c1 - c2)

    def astar(start, goal):
        open_set = [(heuristic(start, goal), 0, start, [start])]
        visited = set()
        while open_set:
            _, cost, current, path = heapq.heappop(open_set)
            if current == goal:
                return path
            if current in visited:
                continue
            visited.add(current)
            for next_cell in neighbors(current):
                if next_cell not in visited:
                    heapq.heappush(open_set, (heuristic(next_cell, goal) + cost + 1, cost + 1, next_cell, path + [next_cell]))
        return None

    path1 = astar(start, goal)
    if path1:
        return path1

    def astar_bidir(start, goal):
        open_start = [(heuristic(start, goal), 0, start, [start])]
        open_goal = [(heuristic(goal, start), 0, goal, [goal])]
        visited_start = {start: (0, None)}
        visited_goal = {goal: (0, None)}
        while open_start and open_goal:
            _, cost, pos, path = heapq.heappop(open_start)
            if pos in visited_goal:
                other_cost, _ = visited_goal[pos]
                if cost + other_cost <= len(grid) * len(grid[0]):
                    full_path = path[:-1] + path_goal[::-1]
                    return full_path
            if pos in visited_start and visited_start[pos][0] < cost:
                continue
            for next_cell in neighbors(pos):
                new_cost = cost + 1
                if next_cell not in visited_start or visited_start[next_cell][0] > new_cost:
                    visited_start[next_cell] = (new_cost, pos)
                    path_start = path + [next_cell]
                    heapq.heappush(open_start, (heuristic(next_cell, goal) + new_cost, new_cost, next_cell, path_start))

            _, cost, pos, path = heapq.heappop(open_goal)
            if pos in visited_start:
                other_cost, _ = visited_start[pos]
                if cost + other_cost <= len(grid) * len(grid[0]):
                    full_path = path_start[::-1] + path[:-1]
                    return full_path
            if pos in visited_goal and visited_goal[pos][0] < cost:
                continue
            for next_cell in neighbors(pos):
                new_cost = cost + 1
                if next_cell not in visited_goal or visited_goal[next_cell][0] > new_cost:
                    visited_goal[next_cell] = (new_cost, pos)
                    path_goal = path + [next_cell]
                    heapq.heappush(open_goal, (heuristic(next_cell, start) + new_cost, new_cost, next_cell, path_goal))
        return None

    return astar_bidir(start, goal)
