    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def jump(r, c, dr, dc):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return r, c
        next_r, next_c = r + dr, c + dc
        if not is_valid(next_r, next_c):
            return None
        if dr != 0 and dc != 0:
            if grid[r][c + dc] == '.' and grid[r + dr][c] == '.' and grid[r + dr][c + dc] == '#':
                return next_r, next_c
        else:
            if grid[r + dr][c + dc] == '#' or (is_valid(r + 2 * dr, c + 2 * dc) and not is_valid(r + dr, c + dc)):
                return next_r, next_c
        return jump(next_r, next_c, dr, dc)

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            res = jump(r, c, dr, dc)
            if res:
                neighbors.append(res)
        return neighbors

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    pq = [(0, start)]
    came_from = {}
    cost = {start: 0}
    while pq:
        _, current = heapq.heappop(pq)
        if current == goal:
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            return path[::-1]
        for next_pos in get_neighbors(*current):
            if not is_valid(*next_pos):
                continue
            new_cost = cost[current] + 1
            if next_pos not in cost or new_cost < cost[next_pos]:
                cost[next_pos] = new_cost
                priority = new_cost + heuristic(next_pos, goal)
                heapq.heappush(pq, (priority, next_pos))
                came_from[next_pos] = current
    return []
