        pq = [(0, start)]
        came_from = {}
        cost_so_far = {start: 0}

        while pq:
            _, current = heapq.heappop(pq)

            if current == goal:
                break

            for dx, dy in directions:
                if reverse:
                    nx, ny = current[0] - dx, current[1] - dy
                else:
                    nx, ny = current[0] + dx, current[1] + dy

                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                    if grid[nx][ny] == '#':
                        continue

                    new_cost = cost_so_far[current] + 1
                    if (nx, ny) not in cost_so_far or new_cost < cost_so_far[(nx, ny)]:
                        cost_so_far[(nx, ny)] = new_cost
                        priority = new_cost + heuristic((nx, ny), goal)
                        heapq.heappush(pq, (priority, (nx, ny)))
                        came_from[(nx, ny)] = current

        return came_from

    forward = a_star(start, goal)
    reverse = a_star(goal, start, reverse=True)

    # Try meet in the middle
    forward_set = set(forward.keys())
    reverse_set = set(reverse.keys())
    intersection = forward_set & reverse_set

    if not intersection:
        return []

    meet_point = next(iter(intersection))

    def reconstruct_path(came_from, start, end):
        path = []
        current = end
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        return path

    forward_path = reconstruct_path(forward, start, meet_point)
    reverse_path = reconstruct_path(reverse, goal, meet_point)

    full_path = forward_path + reverse_path[::-1][1:]

    return full_path
