import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def is_corner(pr, pc, r, c, nr, nc):
        # (pr, pc) -> (r, c) -> (nr, nc)
        # Check if (r, c) is a corner between (pr, pc) and (nr, nc)
        # The current cell is a corner if it's a diagonal to pr and nr
        # and both pr and nr are in different rows and columns than the current
        return pr != r and nr != r and pc != c and nc != c

    def prune(pr, pc, r, c, dir_r, dir_c):
        # Determine if (r,c) is a prunable step from (pr,pc)
        if dir_r != 0 and dir_c != 0:  # diagonal move
            if is_valid(r + dir_r, c) and grid[r + dir_r][c] == '#':
                # Wall to the north or south
                return True
            if is_valid(r, c + dir_c) and grid[r][c + dir_c] == '#':
                # Wall to the east or west
                return True
        return False

    def jump(pr, pc, r, c, dir_r, dir_c):
        # JUMP step in the current direction
        # Returns (r, c) if it is a jump point
        if not is_valid(r, c):
            return None
        if dir_r != 0 and dir_c != 0:
            # Diagonal
            if (is_valid(r + dir_r, c) and grid[r + dir_r][c] == '.') and \
               (is_valid(r, c + dir_c) and grid[r][c + dir_c] == '.') and \
               not is_valid(r + dir_r, c + dir_c):
                return None
            for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + ndr, c + ndc
                if is_valid(nr, nc) and not ((nr == r + dir_r) and (nc == c + dir_c)) and not ((nr == r - dir_r) and (nc == c - dir_c)):
                    if (is_corner(pr, pc, r, c, nr, nc)):
                        return (r, c)
        else:
            # Straight
            if (is_valid(r + dir_r, c) and grid[r + dir_r][c] == '#') or \
               (is_valid(r, c + dir_c) and grid[r][c + dir_c] == '#'):
                return None
            for ndr, ndc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dir_r + ndr, c + dir_c + ndc
                if is_valid(nr, nc):
                    if is_corner(pr, pc, r, c, nr, nc):
                        return (r, c)
        return jump(pr, pc, r + dir_r, c + dir_c, dir_r, dir_c)

    def search(pr, pc, r, c):
        points = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if is_valid(r + dr, c + dc) and (pr != r + dr or pc != c + dc):
                j = jump(pr, pc, r + dr, c + dc, dr, dc)
                if j:
                    points.append((j, dr, dc))
        return points

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]

    pq = [(0, start, None, None)]
    heapq.heapify(pq)
    came_from = {}
    visited = set()

    while pq:
        cost, (r, c), pr, pc = heapq.heappop(pq)
        if (r, c) == goal:
            path = [goal]
            while (r, c) != start:
                r, c = came_from[(r, c)]
                path.append((r, c))
            return path[::-1]
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for (jr, jc), dr, dc in search(pr, pc, r, c):
            if (jr, jc) not in visited and (jr, jc) not in came_from:
                came_from[(jr, jc)] = (r, c)
                heapq.heappush(pq, (0, (jr, jc), r, c))

    return []
