    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, is_forward):
        visited = {}
        frontier = [(heuristic(start, goal), 0, start, None)]
        path_map = {}
        while frontier:
            h, cost, pos, prev = heappop(frontier)
            if pos in visited and visited[pos] <= cost:
                continue
            visited[pos] = cost
            path_map[pos] = prev
            if pos == goal:
                break
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                if (
                    0 <= r < len(grid) and 0 <= c < len(grid[0]) and
                    grid[r][c] == '.' and (r, c) not in visited
                ):
                    new_cost = cost + 1
                    if is_forward:
                        heappush(frontier, (heuristic((r, c), goal) + new_cost, new_cost, (r, c), pos))
                    else:
                        heappush(frontier, (heuristic((r, c), start) + new_cost, new_cost, (r, c), pos))

        # Reconstruct path
        path = []
        curr = goal
        while curr is not None:
            path.append(curr)
            curr = path_map.get(curr)
        return path[::-1] if path else []

    forward_path = a_star(start, goal, is_forward=True)
    backward_path = a_star(goal, start, is_forward=False)

    if len(forward_path) > 0:
        return forward_path
    elif len(backward_path) > 0:
        return backward_path
    else:
        return []
