def solve(grid, start, goal):
    if not is_free(grid, start) or not is_free(grid, goal):
        return []
    if start == goal:
        return [start]

    return jump_point_search(grid, start, goal)

def is_free(grid, pos):
    row, col = pos
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def jump_point_search(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def jump(p, d):
        r, c = p
        dr, dc = d
        nr, nc = r + dr, c + dc
        if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] != '.':
            return None

        if not (dr == 0 and dc == 0) and \
           ((dr != 0 and 0 <= nc - dc < cols and grid[nr][nc - dc] == '.' and \
             (grid[nr - dr][nc] != '.' or is_diagonal_in_cut(grid, r, c, nr, nc, d))):
            res = jump((nr, nc), d)
            if res:
                return res

        if dr != 0 and dc != 0:
            for ortho_d in [(-1, 0), (1, 0)]:
                o_dr, o_dc = ortho_d
                if jump((nr, nc), (o_dr, 0)) or jump((nr, nc), (o_dr, 0)):
                    return (nr, nc)
            for ortho_d in [(0, -1), (0, 1)]:
                o_dr, o_dc = ortho_d
                if jump((nr, nc), (0, o_dr)) or jump((nr, nc), (0, o_dr)):
                    return (nr, nc)
        elif dr != 0:
            for ortho_d in [(0, -1), (0, 1)]:
                o_dr, o_dc = ortho_d
                if jump((nr, nc), (0, o_dc)) or jump((nr, nc), (0, o_dc)):
                    return (nr, nc)
        elif dc != 0:
            for ortho_d in [(-1, 0), (1, 0)]:
                o_dr, o_dc = ortho_d
                if jump((nr, nc), (o_dr, 0)) or jump((nr, nc), (o_dr, 0)):
                    return (nr, nc)

        return (nr, nc)

    def is_diagonal_in_cut(grid, r, c, nr, nc, d):
        dr, dc = d
        if dr == 0 or dc == 0:
            return False
        dr2 = nr - r - dr
        dc2 = nc - c - dc
        if grid[r + dr][c + dc] != '.' or grid[nr][c] != '.' or grid[r][nc] != '.':
            return False
        return True

    open_set = []
    came_from = {}
    g_score = {}
    f_score = {}

    def heuristic(p):
        r, c = p
        g_r, g_c = goal
        return abs(r - g_r) + abs(c - g_c)

    heapq.heappush(open_set, (heuristic(start), start))
    g_score[start] = 0
    f_score[start] = heuristic(start)

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == goal:
            return reconstruct_path(came_from, current)

        for direction in directions:
            jump_point = jump(current, direction)
            if jump_point is not None and is_free(grid, jump_point):
                tentative_g_score = g_score[current] + abs(jump_point[0] - current[0]) + abs(jump_point[1] - current[1])
                if jump_point not in g_score or tentative_g_score < g_score[jump_point]:
                    came_from[jump_point] = current
                    g_score[jump_point] = tentative_g_score
                    f_score[jump_point] = tentative_g_score + heuristic(jump_point)
                    heapq.heappush(open_set, (f_score[jump_point], jump_point))

    return []

def reconstruct_path(came_from, current):
    total_path = [current]
    while current in came_from:
        current = came_from[current]
        total_path.insert(0, current)
    return total_path
