                    heur = abs(nr - goal[0]) + abs(nc - goal[1])
                    heapq.heappush(queue, (new_cost + heur, (nr, nc)))
                    came_from[(nr, nc)] = node

        path = []
        current = goal
        while current in came_from and current != start:
            path.append(current)
            current = came_from[current]
        if current == start:
            path.append(start)
        return path[::-1]

    path1 = a_star(start)
    path2 = a_star(goal, is_reversed=True)

    if path1 and path1[-1] == goal:
        return path1
    elif path2 and path2[-1] == goal:
