        r, c = position
        dr, dc = direction
        neighbors = []
        if dr != 0:
            nr = r + dr
            while 0 <= nr < rows and not is_wall(nr, c):
                neighbors.append((nr, c))
                nr += dr
        if dc != 0:
            nc = c + dc
            while 0 <= nc < cols and not is_wall(r, nc):
                neighbors.append((r, nc))
                nc += dc
        return neighbors

    def jump(r, c, dr, dc):
        if not (0 <= r < rows and 0 <= c < cols):
            return None
        if is_wall(r, c):
            return None
        if dr != 0:
            nr = r + dr
            while 0 <= nr < rows and not is_wall(nr, c):
                if (is_wall(nr - dr, c + 1) or is_wall(nr - dr, c - 1)) and (dc == 0 or dr != 0):
                    return (nr, c)
                nr += dr
        if dc != 0:
            nc = c + dc
            while 0 <= nc < cols and not is_wall(r, nc):
                if (is_wall(r + 1, nc - dc) or is_wall(r - 1, nc - dc)) and (dr == 0 or dc != 0):
                    return (r, nc)
                nc += dc
        return None

    def get_forced_neighbors(r, c, dr, dc):
        forced = []
        if dr != 0 and dc != 0:
            check_r = r + dr
            if 0 <= check_r < rows and not is_wall(check_r, c):
                if is_wall(check_r, c - dc):
                    forced.append((check_r, c - dc))
                if is_wall(check_r, c + dc):
                    forced.append((check_r, c + dc))
        elif dr != 0:
            check_r = r + dr
            if 0 <= check_r < rows and not is_wall(check_r, c):
                if dc != 0:
                    check_rc = c + dc
                    if is_wall(check_r, check_rc):
                        forced.append((check_r, check_rc))
        elif dc != 0:
            check_c = c + dc
            if 0 <= check_c < cols and not is_wall(r, check_c):
                if dr != 0:
                    check_rc = r + dr
                    if is_wall(check_rc, check_c):
                        forced.append((check_rc, check_c))
        return forced

    def get_successors(position, parent):
        r, c = position
        pr, pc = parent
        dr = r - pr
        dc = c - pc
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        successors = []
        for d in directions:
            nr, nc = r + d[0], c + d[1]
            if 0 <= nr < rows and 0 <= nc < cols and not is_wall(nr, nc) and (nr, nc) != parent:
                if d == (dr, dc):
                    next_pos = jump(nr, nc, d[0], d[1])
                    if next_pos:
                        successors.append(next_pos)
                else:
                    successors.append((nr, nc))
        return successors

    open_set = [(0, 0, start, None)]
    visited = set()
    cost = {start: 0}
    parent = {start: None}

    while open_set:
        _, g, pos, p = heapq.heuristic_pop(open_set)
        if pos == goal:
            path = []
            while pos:
