from heapq import heappush, heappop

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return r < 0 or c < 0 or r >= len(grid) or c >= len(grid[0]) or grid[r][c] == '#'

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if not is_wall((nr, nc)):
                yield (nr, nc)

    if is_wall(start) or is_wall(goal):
        return []
    if start == goal:
        return [start]

    def heuristic(pos, target):
        pr, pc = pos
        tr, tc = target
        return abs(pr - tr) + abs(pc - tc)

    class AStar:
        def __init__(self, start, goal):
            self.start = start
            self.goal = goal
            self.frontier = [(heuristic(start, goal), start)]
            self.came_from = {}
            self.cost = {start: 0}
            self.f = {start: heuristic(start, goal)}

        def run(self, neighbors):
            while self.frontier:
                _, current = heappop(self.frontier)
                if current == self.goal:
                    return True
                if current in self.came_from:
                    continue
                for next_pos in neighbors(current):
                    if next_pos not in self.cost and next_pos not in self.came_from:
                        self.cost[next_pos] = self.cost[current] + 1
                        new_f = self.cost[next_pos] + heuristic(next_pos, self.goal)
                        self.f[next_pos] = new_f
                        heappush(self.frontier, (new_f, next_pos))
                        self.came_from[next_pos] = current
            return False

        def get_path(self):
            if self.goal not in self.came_from:
                return None
            path = [self.goal]
            while path[-1] != self.start:
                path.append(self.came_from[path[-1]])
            path.reverse()
            return path

    forward = AStar(start, goal)
    backward = AStar(goal, start)

    found = False
    while forward.frontier or backward.frontier:
        if forward.frontier:
            if forward.run(neighbors):
                found = True
                break
        if backward.frontier:
            if backward.run(neighbors):
                found = True
                break

    if not found:
        return reverse_path := forward.get_path() or backward.get_path()
        if not reverse_path:
            return []
        return reverse_path

    forward_vertices = set(forward.cost)
    backward_vertices = set(backward.cost)

    cross = forward_vertices & backward_vertices
    if not cross:
        return []

    best_node = min(cross, key=lambda n: forward.cost[n] + backward.cost[n])
    forward_path = forward.get_path()
    backward_path = backward.get_path()

    idx = forward_path.index(best_node)
    rev_idx = backward_path.index(best_node) if backward_path else -1
    if idx == -1 or rev_idx == -1:
        return []

    full_path = forward_path[:idx+1] + backward_path[rev_idx:][::-1]
    return full_path
