        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    forward = a_star_search(start, goal, is_reversed=False)
    backward = a_star_search(goal, start, is_reversed=True)

    if start not in forward or goal not in backward:
        return []

    intersection = set(forward).intersection(backward)
    if not intersection:
        return []

    total_path = []
    for cell in sorted(intersection, key=lambda x: len(forward[cell]) + len(backward[x])):
        path = forward[cell] + backward[cell][::-1]
        if is_valid_path(grid, path):
            return path

    return []

def is_valid_path(grid, path):
    for i in range(len(path)-1):
        r1, c1 = path[i]
        r2, c2 = path[i+1]
        if abs(r1 - r2) + abs(c1 - c2) != 1:
            return False
        if grid[r1][c1] != '.' or grid[r2][c2] != '.':
            return False
    return True
