import heapq

def solve(grid, start, goal):
    if is_wall(grid, *start) or is_wall(grid, *goal):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in directions if not is_wall(r + dr, c + dc)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump(r, c, d, came_from):
        dr, dc = d
        nr, nc = r + dr, c + dc
        if is_wall(nr, nc):
            return None
        forced_neighbors = []

        if dr != 0 and dc != 0:
            forced_neighbors = [(r + dr, c), (r, c + dc)]  # Diagonal, check adjacent
        elif dr != 0:
            forced_neighbors = [(r + dr, c) if is_wall(r + dr * 2, c) else []]  # Vertical
        elif dc != 0:
            forced_neighbors = [(r, c + dc) if is_wall(r, c + dc * 2) else []]  # Horizontal

        for (x, y) in forced_neighbors:
            if (x, y) not in came_from and not is_wall(x, y):
                return (nr, nc)
        came_from[(nr, nc)] = (r, c)
        jumped = jump(nr, nc, d, came_from)
        if jumped is not None:
            return jumped
        return None

    came_from = {start: None}
    open_set = [(heuristic(start, goal), start)]

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == goal:
            break

        for d in directions:
            jump_point = jump(*current, d, came_from)
            if jump_point and jump_point not in came_from:
                came_from[jump_point] = current
                heapq.heappush(open_set, (heuristic(jump_point, goal), jump_point))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current:
        path.append(current)
        current = came_from[current]
    path.reverse()

    return path
