import heapq

def solve(grid, start, goal):
    if is_wall(grid, start) or is_wall(grid, goal):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(grid, pos):
        r, c = pos
        if not is_in_bounds(pos):
            return True
        return grid[r][c] == '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_in_bounds((nr, nc)) and not is_wall(grid, (nr, nc)):
                neighbors.append((nr, nc))
        return neighbors

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
        return total_path[::-1]

    def is_corner(grid, r, c, dr, dc):
        return (is_wall(grid, (r, c + dc)) or is_wall(grid, (r + dr, c)))

    def jump(pos, delta, parent):
        r, c = pos
        dr, dc = delta
        nr, nc = r + dr, c + dc
        if not is_in_bounds((nr, nc)) or is_wall(grid, (nr, nc)):
            return None
        if (nr, nc) == goal:
            return (nr, nc)
        # Horizontal/vertical
        if dr == 0 or dc == 0:
            if (parent[0] != r or parent[1] != c) and is_corner(grid, r, c, dr, dc):
                return (r, c)
            if jump((r + dr, c + dc), (dr, dc), (r, c)):
                return jump((r + dr, c + dc), (dr, dc), (r, c))
            return None
        # Diagonal
        else:
            if is_wall(grid, (r + dr, c)) or is_wall(grid, (r, c + dc)):
                return (r, c)
            if (jump((r, c + dc), (0, dc), (r, c)) or jump((r + dr, c), (dr, 0), (r, c))):
                return (r, c)
            next_pos = jump((r + dr, c + dc), (dr, dc), (r, c))
            if next_pos:
                # Check if the next can be reached from any orthogonal direction
                nr, nc = next_pos
                for d in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    if jump((nr, nc), d, (nr - d[0], nc - d[1])):
                        return next_pos
            return next_pos

    def get_jps_neighbors(pos, parent):
        r, c = pos
        neighbors = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_in_bounds((nr, nc)) and not is_wall(grid, (nr, nc)):
                if (parent[0] != nr or parent[1] != nc):
                    result = jump((r, c), (dr, dc), parent)
                    if result:
                        neighbors.append(result)
        return neighbors

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}
    parent = {start: start}

    while open_set:
        current = heapq.heappop(open_set)[1]
        if current == goal:
            return reconstruct_path(came_from, current)

        for next_pos in get_jps_neighbors(current, parent[current]):
            if is_wall(grid, next_pos):
                continue
            tentative_g_score = g_score[current] + 1
            if tentative_g_score < g_score.get(next_pos, float('inf')):
                came_from[next_pos] = current
                g_score[next_pos] = tentative_g_score
                f_score[next_pos] = tentative_g_score + heuristic(next_pos, goal)
                heapq.heappush(open_set, (f_score[next_pos], next_pos))
                parent[next_pos] = current

    return []
