        while node is not None:
            path.append(node)
            node = forward[node]
        path.reverse()
        node = backward[node]
        while node is not None:
            path.append(node)
            node = backward[node]
        return path

    while queue_forward and queue_backward:
        # Forward step
        pos = queue_forward.popleft()
        for neighbor in get_neighbors(pos):
            if neighbor not in visited_forward:
                visited_forward[neighbor] = pos
                queue_forward.append(neighbor)
                if neighbor in visited_backward:
                    return reconstruct_path(visited_forward, visited_backward)

        # Backward step
        pos = queue_backward.popleft()
        for neighbor in get_neighbors(pos):
            if neighbor not in visited_backward:
                visited_backward[neighbor] = pos
                queue_backward.append(neighbor)
                if neighbor in visited_forward:
