        return [(nr, nc) for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] if not is_wall((nr, nc))]

    def heuristic(pos, target):
        pr, pc = pos
        tr, tc = target
        return abs(pr - tr) + abs(pc - tc)

    def a_star(start, goal, reverse):
        from collections import deque
        import heapq

        fringe = []
        heapq.heappush(fringe, (heuristic(start, goal), 0, start))
        came_from = {start: None}
        cost_so_far = {start: 0}

        while fringe:
            _, dist, current = heapq.heappop(fringe)
            if current == goal:
                break
            for next_pos in neighbors(current):
                if reverse:
                    next_pos, current = current, next_pos
                new_cost = dist + 1
                if next_pos not in cost_so_far or new_cost < cost_so_far[next_pos]:
                    cost_so_far[next_pos] = new_cost
                    priority = new_cost + heuristic(next_pos, goal)
                    heapq.heappush(fringe, (priority, new_cost, next_pos))
                    came_from[next_pos] = current

        if goal not in came_from:
            return None

        path = []
        current = goal
        while current:
            path.append(current)
            current = came_from[current]
        return path[::-1]

    if is_wall(start) or is_wall(goal):
        return []
    if start == goal:
        return [start]
    forward_path = a_star(start, goal, reverse=False)
    backward_path = a_star(goal, start, reverse=True)

    # Bidirectional A*: connect paths if both reach forward and backward
    if forward_path is not None and backward_path is not None:
        forward_set = set(forward_path)
        for i, p in enumerate(backward_path):
            if p in forward_set:
                idx = forward_path.index(p)
                return forward_path[:idx+1] + backward_path[i+1:][::-1]
    return forward_path if forward_path is not None else []
