import heapq

def solve(grid, start, goal):
    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.')

    if is_wall(*start) or is_wall(*goal):
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def search(frontier, visited, reverse):
        while frontier:
            g, pos = heapq.heappop(frontier)
            if pos in visited:
                continue
            visited[pos] = g
            if reverse and pos == start or not reverse and pos == goal:
                return True
            r, c = pos
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if not is_wall(nr, nc) and (nr, nc) not in visited:
                    heapq.heappush(frontier, (g + 1, (nr, nc)))
        return False

    from_start = []
    from_goal = []
    visited_start = {}
    visited_goal = {}
    frontier_start = [(0, start)]
    frontier_goal = [(0, goal)]
    path_found = False

    while frontier_start or frontier_goal:
        if search(frontier_start, visited_start, False):
            path_found = True
            break
        if search(frontier_goal, visited_goal, True):
            path_found = True
            break

        if not frontier_start or not frontier_goal:
            break

    if not path_found:
        return []

    path = set(visited_start.keys()).intersection(visited_goal.keys())
    if not path:
        return []

    node = min(path, key=lambda p: visited_start[p] + visited_goal[p])
    def build_path(start_dict, end_dict, node):
        res = []
        p = node
        while p != start:
            r, c = p
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in start_dict and start_dict[(nr, nc)] == start_dict[p] - 1:
                    res.append((nr, nc))
                    p = (nr, nc)
                    break
        res.reverse()
        p = node
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) in end_dict and end_dict[(nr, nc)] == end_dict[p] - 1:
                p = node
                break
        while p != goal:
            r, c = p
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in end_dict and end_dict[(nr, nc)] == end_dict[p] - 1:
                    p = (nr, nc)
                    res.append(p)
                    break
        return res

    return [start] + build_path(visited_start, visited_goal, node) + [goal]
