import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) \
       or not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    def is_wall(r, c):
        return grid[r][c] == '#'

    if is_wall(*start) or is_wall(*goal):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    diagonal = [(-1, -1), (-1, 1), (1, -1), (1, 1)]  # diagonals for prunning

    def is_in_grid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0])

    def get_prunned_neighbors(r, c, dirr, dirc):
        neighbors = []
        if dirr == 0 and dirc == 0:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_in_grid(nr, nc) and not is_wall(nr, nc):
                    if (r - dr, c - dc) != (start[0], start[1]) or (r, c) == start:
                        if (dr == 0 or dirc != 0) and (dc == 0 or dirr != 0):
                            neighbors.append((nr, nc))
        else:
            # Pruned diagonal step
            for ddr, ddc in diagonal:
                if dirr != 0 and dirr * ddr < 0:
                    continue
                if dirc != 0 and dirc * ddc < 0:
                    continue
                nr, nc = r + ddr, c + ddc
                if is_in_grid(nr, nc) and not is_wall(nr, nc):
                    neighbors.append((nr, nc))
        return neighbors

    def find_jumps(r, c, dirr, dirc):
        if not is_in_grid(r, c) or is_wall(r, c):
            return None
        if (r, c) == goal:
            return (r, c)

        next_r = r + dirr
        next_c = c + dirc
        next_p = (next_r, next_c)

        if not is_in_grid(next_r, next_c) or is_wall(next_r, next_c):
            return None

        # Check horizontal/vertical jump
        if dirr != 0 and dirc == 0:
            if not is_wall(r + dirr, c + 1) or not is_wall(r + dirr, c - 1):
                return next_p
        elif dirc != 0 and dirr == 0:
            if not is_wall(r + 1, c + dirc) or not is_wall(r - 1, c + dirc):
                return next_p
        # Check diagonal jump
        elif dirr != 0 and dirc != 0:
            if not (is_wall(r + dirr, c) or is_wall(r, c + dirc)):
                return next_p
            if not is_wall(next_r, next_c):
                # Recursively check diagonal paths
                right = find_jumps(r, c + dirc, 0, dirc)
                down = find_jumps(r + dirr, c, dirr, 0)
                if right or down:
                    return next_p

        next_next_p = find_jumps(next_r, next_c, dirr, dirc)
        return next_next_p if next_next_p else None

    class Node:
        def __init__(self, pos, parent=None):
            self.pos = pos
            self.parent = parent

        def get_children(self):
            children = []
            for dr, dc in directions:
                if (self.pos[0] + dr, self.pos[1] + dc) == self.parent and self.parent:
                    continue
                jump_pos = find_jumps(self.pos[0], self.pos[1], dr, dc)
                if jump_pos:
                    children.append(Node(jump_pos, self))
            return children

        def __eq__(self, other):
            return self.pos == other.pos

        def __hash__(self):
            return hash(self.pos)

    open_set = [Node(start)]
    visited = set([start])
    heapq.heapify(open_set)

    while open_set:
        cur = heapq.heappop(open_set)
        if cur.pos == goal:
            path = []
            node = cur
            while node:
                path.append(node.pos)
                node = node.parent
            return path[::-1]
        for child in cur.get_children():
            if child.pos not in visited and not is_wall(*child.pos):
                visited.add(child.pos)
                heapq.heappush(open_set, child)
    return []
