        return []

    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    directions = [(-1,0),(1,0),(0,-1),(0,1)]  # Up, Down, Left, Right
    parents = {}
    open_list = [(0, start)]
    visited = set()

    def get_neighbors(node, direction_used):
        neighbors = []
        r, c = node
        dr, dc = direction_used
        if dr != 0:  # Vertical direction
            if dr == -1:  # Up
                if r > 0:
                    if grid[r - 1][c] == '.' and grid[r - 2][c] == '.':
                        neighbors.append((r - 2, c))
            else:  # Down
                if r < len(grid) - 1:
                    if grid[r + 1][c] == '.' and grid[r + 2][c] == '.':
                        neighbors.append((r + 2, c))
            if c > 0 and grid[r][c - 1] == '.':
                neighbors.append((r, c - 1))
            if c < len(grid[0]) - 1 and grid[r][c + 1] == '.':
                neighbors.append((r, c + 1))
        elif dc != 0:  # Horizontal direction
            if dc == -1:  # Left
                if c > 0:
                    if grid[r][c - 1] == '.' and grid[r][c - 2] == '.':
                        neighbors.append((r, c - 2))
            else:  # Right
                if c < len(grid[0]) - 1:
                    if grid[r][c + 1] == '.' and grid[r][c + 2] == '.':
                        neighbors.append((r, c + 2))
            if r > 0 and grid[r - 1][c] == '.':
                neighbors.append((r - 1, c))
            if r < len(grid) - 1 and grid[r + 1][c] == '.':
                neighbors.append((r + 1, c))
        return neighbors

    def jump_point(node, parent_dir):
        r, c = node
        dr, dc = parent_dir

        # Check for forced neighbors
        # First handle the vertical and horizontal dir
        if parent_dir in [(-1,0),(1,0),(0,-1),(0,1)]:
            if dr != 0:  # Vertical
                next_r = r + dr
                if 0 <= next_r < len(grid) and grid[next_r][c] != '.':
                    return None
                if c > 0 and grid[next_r][c - 1] == '.':
                    return (next_r, c - 1)
                if c < len(grid[0]) - 1 and grid[next_r][c + 1] == '.':
                    return (next_r, c + 1)
                return jump_point((next_r, c), parent_dir) if is_valid(next_r, c) else None
            elif dc != 0:  # Horizontal
                next_c = c + dc
                if 0 <= next_c < len(grid[0]) and grid[r][next_c] != '.':
                    return None
                if r > 0 and grid[r - 1][next_c] == '.':
                    return (r - 1, next_c)
                if r < len(grid) - 1 and grid[r + 1][next_c] == '.':
                    return (r + 1, next_c)
                return jump_point((r, next_c), parent_dir) if is_valid(r, next_c) else None

        # This should return new jump points for diagonal directions
        for dr2, dc2 in directions:
            if dr2 != dr and dc2 != dc:
                next_node = (r + dr2, c + dc2)
                if is_valid(*next_node) and grid[next_node[0]][next_node[1]] == '.':
                    return next_node
        return None

    cost = {start: 0}
    while open_list:
        _, node = heapq.heuristicq(open_list)
        if node == goal:
            path = [node]
            while node in parents:
                node = parents[node]
                path.append(node)
            return path[::-1]
        if node in visited:
            continue
        visited.add(node)

        for dr, dc in directions:
            neighbor = (node[0] + dr, node[1] + dc)
            if is_valid(*neighbor):
                new_cost = cost[node] + 1
                if neighbor not in cost or new_cost < cost[neighbor]:
                    cost[neighbor] = new_cost
                    parents[neighbor] = node
                    heapq.heappush(open_list, (new_cost + ((goal[0] - neighbor[0])**2 + (goal[1] - neighbor[1])**2)**0.5, neighbor))
                    jps = jump_point(neighbor, (dr, dc))
                    if jps and jps not in visited and is_valid(*jps):
                        heapq.heappush(open_list, (cost[neighbor] + 1 + ((goal[0] - jps[0])**2 + (goal[1] - jps[1])**2)**0.5, jps))

    return []
