import heapq

def solve(grid, start, goal):
    if is_wall(grid, *start) or is_wall(grid, *goal):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    neighbors = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump(r, c, dir_r, dir_c):
        if not is_free(r, c):
            return None
        if (r, c) == goal:
            return (r, c)

        # Check if current cell is a forced neighbor, or if there's an obstacle
        # in the straight direction.
        for ndr, ndc in [(0, dir_c), (dir_r, 0)]:
            nr, nc = r + ndr, c + ndc
            if (nr, nc) != (r + dir_r, c + dir_c) and 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '#' and not (nr == r and nc == c):
                return (r, c)

        # Continue in the straight direction
        nr, nc = r + dir_r, c + dir_c
        if is_free(nr, nc):
            return jump(nr, nc, dir_r, dir_c)
        else:
            return None

    def get_successors(r, c):
        succ = []
        for dr, dc in neighbors:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                # Jump if straight path
                if dr != 0 and dc != 0:
                    continue
                j = jump(r, c, dr, dc)
                if j:
                    succ.append(j)
        return succ

    def direction(r1, c1, r2, c2):
        return (1 if r2 > r1 else -1 if r2 < r1 else 0, 1 if c2 > c1 else -1 if c2 < c1 else 0)

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current, start)

        for neighbor in get_successors(*current):
            nr, nc = neighbor
            if not is_free(nr, nc):
                continue
            tentative_g = g_score[current] + 1
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []

def reconstruct_path(came_from, current, start):
    path = [current]
    while current != start:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path
