            return None

        if (dx != 0 and dy == 0):  # Vertical move
            if is_valid(x + dx, y) and (grid[x + dx][y] == '.' and not (
                    (x + dx != start[0] or y != start[1]) and grid[x + dx][y] == '.' and (
                            (is_valid(x + 2 * dx, y) and grid[x + 2 * dx][y] == '.')
                            or (is_valid(x + dx, y + 1) and grid[x + dx][y + 1] == '.'))
            )):
                return None

        if (dy != 0 and dx == 0):  # Horizontal move
            if is_valid(x, y + dy) and (grid[x][y + dy] == '.' and not (
                    (x != start[0] or y + dy != start[1]) and grid[x][y + dy] == '.' and (
                            (is_valid(x, y + 2 * dy) and grid[x][y + 2 * dy] == '.')
                            or (is_valid(x + 1, y + dy) and grid[x + 1][y + dy] == '.'))
            )):
                return None

        if dx != 0 and dy != 0:  # Diagonal move
            if not (is_valid(x + dx, y) or is_valid(x, y + dy) or is_valid(x + dx, y + dy)):
                return None

        if dx != 0:
            nx = x + dx
            ny = y
            if not is_valid(nx, ny):
                return None
            if (is_valid(nx, y + 1) and grid[nx][y + 1] == '.') or \
                    (is_valid(nx, y - 1) and grid[nx][y - 1] == '.'):
                return (nx, ny)
        if dy != 0:
            nx = x
            ny = y + dy
            if not is_valid(nx, ny):
                return None
            if (is_valid(x + 1, ny) and grid[x + 1][ny] == '.') or \
                    (is_valid(x - 1, ny) and grid[x - 1][ny] == '.'):
                return (nx, ny)

        if (dx != 0 or dy != 0):
            (nx, ny) = jump(x + dx, y + dy, dx, dy, dir)
            if nx is not None and ny is not None:
                return (nx, ny)
        return None

    def get_neighbors(x, y):
        neighbors = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx = x + dx
            ny = y + dy
            if is_valid(nx, ny):
                jx, jy = jump(x, y, dx, dy, (dx, dy))
                if jx is not None and jy is not None:
                    neighbors.append((jx, jy))
        return neighbors

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
        return total_path[::-1]

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: abs(start[0] - goal[0]) + abs(start[1] - goal[1])}

    while open_set:
        current = heapq.heappop(open_set)[1]
        if current == goal:
            return reconstruct_path(came_from, current)

        for neighbor in get_neighbors(current[0], current[1]):
            tentative_g = g_score[current] + 1
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = g_score[neighbor] + abs(neighbor[0] - goal[0]) + abs(neighbor[1] - goal[1])
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []
